const got = $input.first().json.headers?.['x-gaiada-bridge-secret'];
if (!got || got !== $env.N8N_BRIDGE_SECRET) throw new Error('bad bridge secret');
const e = $input.first().json.body ?? {};
if (e.v !== 1) throw new Error('bad envelope v');
const runId = e.payload?.runId ?? e.entityId;
const store = $getWorkflowStaticData('global'); store.seen = store.seen || {};
const dup = Object.prototype.hasOwnProperty.call(store.seen, e.id);
if (!dup) { store.seen[e.id] = Date.now(); const ids = Object.keys(store.seen); if (ids.length > 1000) for (const k of ids.slice(0, ids.length - 1000)) delete store.seen[k]; }
return [{ json: { dup, tenantId: e.tenantId, runId } }];

