const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'getRun failed');
const run = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}');
const stages = run.stages||[], gates = run.gates||[], signoffs = run.scopeSignoffs||[];
const prdSigned = gates.some(g=>g.kind==='prd_sign'&&g.decision==='signed');
const scopeSigned = (signoffs.some(s=>s.party==='provider')&&signoffs.some(s=>s.party==='client'))||gates.some(g=>g.kind==='scope_signoff'&&g.decision==='signed');
const designs = stages.filter(s=>s.name==='claude_design'); const design = designs[designs.length-1];
const code = stages.find(s=>s.name==='claude_code'); const staging = stages.find(s=>s.name==='staging'); const prodStage = stages.find(s=>s.name==='production');
const MAX_DESIGNS = 3;
const gof=(kind,sid)=>gates.filter(g=>g.kind===kind&&g.stage_id===sid).sort((a,b)=>a.created_at<b.created_at?-1:1).pop();
const ok=g=>g&&g.status==='decided'&&g.decision==='approved';
const has=(kind,sid)=>gates.some(g=>g.kind===kind&&g.stage_id===sid);
const prd=(stages.find(s=>s.name==='prd_extract')||{}).artifact_ref||'';
const slug=String(run.title||('run-'+run.id)).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40);
let action='noop',nextKind='',nextActor='',stageId='',note='';
// WD-05: a run already parked 'blocked' (revise-budget exhausted) short-circuits to noop on any
// later retrigger (a second gate.decided/scope.signed on the same run must not re-escalate it).
if(run.status==='blocked'){ /* noop */ }
else if(prdSigned&&scopeSigned){
  if(!design){action='release_design';}
  else {
    const cfd=gof('customer_feedback',design.id);
    if(ok(gof('pm_review',design.id))&&!has('customer_feedback',design.id)){action='open_gate';nextKind='customer_feedback';nextActor='client';stageId=design.id;note='Submission beat 2 — client feedback';}
    else if(cfd&&cfd.status==='decided'&&cfd.decision==='changes_requested'){ if(designs.length<MAX_DESIGNS){action='revise_design';note=cfd.note||'';} else {action='escalate_revise';note=cfd.note||'';} }
    else if(ok(cfd)&&!has('pm_approval',design.id)){action='open_gate';nextKind='pm_approval';nextActor='internal';stageId=design.id;note='Submission beat 3 — PM approval';}
    else if(ok(gof('pm_approval',design.id))&&!code){action='release_code';}
    else if(code&&ok(gof('pm_review',code.id))&&!staging){action='deploy';}
    else if(staging&&ok(gof('customer_feedback',staging.id))&&!has('pm_approval',staging.id)){action='open_gate';nextKind='pm_approval';nextActor='internal';stageId=staging.id;note='Production approval';}
    else if(staging&&ok(gof('pm_approval',staging.id))&&!prodStage){action='deploy_prod';}
  }
}
const proto=(design||{}).artifact_ref||'';
return [{ json: { tenantId: run.tenant_id, runId: run.id, action, nextKind, nextActor, stageId, note, prd, proto, slug } }];

