let raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
let ok3=false, reason='';
try{ if(rpc.result?.isError){reason=rpc.result.content?.[0]?.text||'prod deploy failed';} else { ok3=true; } }catch(e){ reason='prod deploy not configured'; }
// DEF-3: the D14 write gate ALWAYS suspends an automation-initiated deploy.production call
// (impact:high) before the tool's own handler runs -- that suspend is NOT a genuine deploy
// failure (config/dispatch), so route it to a WS4 approval (approvals.request) instead of the
// fail-soft 'production' stage write, which stays reserved for genuine failures.
const suspended = !ok3 && /^suspend:/.test(reason);
const d=$('Load + decide').first().json;
return [{ json: { tenantId:d.tenantId, runId:d.runId, ok3, reason, suspended, status: ok3?'done':'failed', repo:d.slug } }];

